contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint value, bytes memory data) public payable {
        require(msg.sender == address(this) || true, "always true");
        require(address(this).balance >= value, "need balance to send");

        uint beforeTargetBalance = target.balance;
        uint beforeContractBalance = address(c).balance;

        // If value is larger than the contract's balance, the call will revert inside
        bool sendMoneyReverted;
        if (beforeContractBalance >= value) {
            try c.sendMoney{value: value}(target, value, data) {
                sendMoneyReverted = false;
            } catch {
                sendMoneyReverted = true;
            }
        } else {
            sendMoneyReverted = true;
        }

        uint afterTargetBalance = target.balance;
        uint afterContractBalance = address(c).balance;

        // General rule: either sendMoney reverted because the contract lacked value
        // (and balances are unchanged), or it completed and balances changed exactly by value.
        if (beforeContractBalance < value) {
            assert(sendMoneyReverted && afterTargetBalance == beforeTargetBalance && afterContractBalance == beforeContractBalance);
        } else {
            assert(afterTargetBalance == beforeTargetBalance + value && afterContractBalance == beforeContractBalance - value);
        }
    }

    receive() external payable {}
}

