    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        // Send some Ether to c through its fallback so c has a balance to withdraw.
        address(c).call{value: amount}("");

        uint beforeC = address(c).balance;
        require(beforeC == amount, "c balance should equal the sent amount");

        address ownerBefore = c.owner();
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // For the owner (this test contract), withdrawAll must succeed
        // and move exactly the whole prior balance of c to the owner.
        assert(
            !reverted
                && ownerBefore == address(this)
                && address(c).balance == 0
                && address(this).balance == amount
        );
    }

    receive() external payable {}
}

